function getEntriesByPath(object, path) {
    const parts = path.split('.');
    let current = object;

    for (let i = 0; i < parts.length - 1; i++) {
        if (!(parts[i] in current)) {
            // If any part of the path does not exist in the current level, return undefined/null
            return null;
        }

        current = current[parts[i]];
    }

    // Check if we reached the end of the path with valid values
    if (!(parts[parts.length - 1] in current)) {
        // If the final part doesn't exist either, return undefined/null
        return null;
    } else {
        // Otherwise, return the value at the end of the path
        return current[parts[parts.length - 1]];
    }
}

